CREATE POLICY "raw_material_inventory_write" ON public.raw_material_inventory
  FOR ALL TO authenticated USING (is_pos_admin()) WITH CHECK (is_pos_admin());

CREATE TABLE IF NOT EXISTS public.raw_material_batches (
