FOR UPDATE TO authenticated
USING (
  public.is_platform_admin()
  OR (public.can_permission('floor_plan.manage') AND public.user_may_access_branch(branch_id))
)
WITH CHECK (
  public.is_platform_admin()
  OR (public.can_permission('floor_plan.manage') AND public.user_may_access_branch(branch_id))
);

